  "RECAP_CASES": [
    {
      "id": "r1",
      "text": {
        "ga": "Thug AI figiúr beacht — “tá 64% de na custaiméirí sásta” — gan foinse ar bith.",
        "en": "The AI gave a precise figure — “64% of customers are satisfied” — with no source at all."
      }
    },
    {
      "id": "r2",
      "text": {
        "ga": "Ba mhaith leat ríomhphost ó chustaiméir, lena ainm agus a sheoladh, a ghreamú isteach in uirlis phoiblí.",
        "en": "You want to paste a customer’s email, with their name and address, into a public tool."
      }
    },
    {
      "id": "r3",
      "text": {
        "ga": "Tá fógra Gaeilge réidh le foilsiú. Níor léigh duine ar bith é ach an AI.",
        "en": "An Irish notice is ready to publish. Nobody has read it except the AI."
      }
    },
    {
      "id": "r4",
      "text": {
        "ga": "Fuair tú freagra lag, ginearálta. Níor thug tú comhthéacs ar bith don uirlis.",
        "en": "You got a weak, generic answer. You gave the tool no context at all."
      }
    },
    {
      "id": "r5",
      "text": {
        "ga": "Deir an achoimre go bhfuil páirceáil ar fáil. Ní fios cén doiciméad a deir é sin.",
        "en": "The summary says parking is available. Nobody knows which document says so."
      }
    },
    {
      "id": "r6",
      "text": {
        "ga": "D’fhreagair uirlis amháin go maith i nGaeilge; ní dhearna an dara ceann é.",
        "en": "One tool answered well in Irish; the second did not."
      }
    },
    {
      "id": "r7",
      "text": {
        "ga": "Iarrann bainisteoir ort AI a úsáid chun cinneadh a dhéanamh faoi iarratas ó dhuine ar sheirbhís.",
        "en": "A manager asks you to use AI to decide on a person’s application for a service."
      }
    },
    {
      "id": "r8",
      "text": {
        "ga": "Tá an dréacht go maith. Níl a fhios ag aon duine cé a cheadóidh é.",
        "en": "The draft is good. Nobody knows who will approve it."
      }
    }
  ],
